import{_ as t,o as l,c as s,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/benutzer-einstellungen/verwaltung-einstellungen-faecher-noten-aufrufen.png",u="/bilder/benutzer-einstellungen/verwaltung-einstellungen-faecher-noten-faecher-noten.png",o="/bilder/benutzer-einstellungen/verwaltung-einstellungen-faecher-noten-eingabemodus.png",g="/bilder/benutzer-einstellungen/verwaltung-einstellungen-faecher-noten-max-bemerkungen.png",d="/bilder/benutzer-einstellungen/verwaltung-einstellungen-faecher-noten-farben.png",_=JSON.parse('{"title":"Fächer, Noten und Eingabemodi einstellen","description":"","frontmatter":{"title":"Fächer, Noten und Eingabemodi einstellen","source_pageid":402,"source_revision":3316},"headers":[],"relativePath":"administration/benutzer-einstellungen/faecher-noten-verwaltung-globale-einstellungen.md","filePath":"administration/benutzer-einstellungen/faecher-noten-verwaltung-globale-einstellungen.md"}'),h={name:"administration/benutzer-einstellungen/faecher-noten-verwaltung-globale-einstellungen.md"};function c(m,i,b,p,f,k){return l(),s("div",null,[...i[0]||(i[0]=[r('<h1 id="facher-noten-und-eingabemodi-einstellen" tabindex="-1">Fächer, Noten und Eingabemodi einstellen <a class="header-anchor" href="#facher-noten-und-eingabemodi-einstellen" aria-label="Permalink to &quot;Fächer, Noten und Eingabemodi einstellen&quot;">​</a></h1><p>Legen Sie die globalen Regeln für Noteneingabe, Fehlstunden und Teilleistungen fest. Weitere Optionen steuern Bemerkungslängen und die Farbdarstellung von Fächergruppen.</p><p><a href="/bilder/benutzer-einstellungen/verwaltung-einstellungen-faecher-noten-aufrufen.png"><img src="'+a+'" alt="Rufen Sie die Einstellungen für Fächer und Noten auf." loading="lazy"></a></p><p><em>Rufen Sie die Einstellungen für <strong>Fächer und Noten</strong> auf.</em></p><p>Die für SchILD-NRW global geltenden Optionen für Fächer und Noten finden sich unter <em>Einstellungen ➜ Fächer, Noten</em>.</p><p>Unter diesem Menü finden sich Einstellungen zu</p><ul><li>Fächern und Noten</li><li>dem Eingabemodus für Teilleistungen und Fehlstunden</li><li>der maximalen Länge von Bemerkungen</li><li>Farbeinstellungen für Fächergruppen</li></ul><h2 id="facher-noten" tabindex="-1">Fächer, Noten <a class="header-anchor" href="#facher-noten" aria-label="Permalink to &quot;Fächer, Noten&quot;">​</a></h2><p><a href="/bilder/benutzer-einstellungen/verwaltung-einstellungen-faecher-noten-faecher-noten.png"><img src="'+u+'" alt="Die Einstellungen zu Fächern und Noten." loading="lazy"></a></p><p><em>Die Einstellungen zu Fächern und Noten.</em></p><ul><li><p><strong>Beim Holen abgeschlossener Fächer auch solche ohne numerische Note berücksichtigen</strong> bezieht auch Fächer ein, deren Ergebnis als Text oder Kürzel erfasst ist, zum Beispiel <strong>E1</strong> für <strong>mit besonderem Erfolg teilgenommen</strong>. Das gilt für früher abgeschlossene Fächer, die auf dem aktuellen Zeugnis benötigt werden.</p></li><li><p><strong>Noteneingabe durch alle Beteiligten erlauben</strong> gestattet auch weiteren an der Note beteiligten Personen die Eingabe, etwa Klassenleitungen, Abteilungsleitungen und Zusatzkräften neben den Fachlehrkräften.</p></li><li><p><strong>Eine nicht gemahnte 5 oder 6 bei Versetzungs-/Abschlussberechnungen ignorieren</strong>: Setzen oder entfernen Sie diesen Haken, je nachdem ob Sie die Berechnung für einen <em>Abschlussjahrgang</em> oder einen <em>&quot;normalen&quot; Jahrgang</em> durchführen wollen.</p></li></ul>',11),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),n("Wichtig")]),e("p",null,"Bei Jahrgängen, in denen ein Schulabschluss vergeben wird, können unter Umständen auch nicht gemahnte Defizite versetzungsrelevant sein. Richten Sie sich nach der jeweils geltenden APO.")],-1),e("ul",null,[e("li",null,[e("strong",null,"Doppelte Fächer in Leistungsdaten vermeiden"),n(": Durch Aktivierung dieser Option versucht SchILD-NRW bei Importen von Fächern eine Erkennung von Doppelungen und versucht, diese zu vermeiden.")])],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Dieser Haken muss auch gesetzt sein, wenn der "),e("em",null,"Gruppenprozess"),n(),e("strong",null,"Doppelte Fächer löschen"),n(" ausgeführt werden soll.")])],-1),r('<ul><li><strong>Erweiterte Noten in der Sek. I zulassen</strong> erlaubt bei einer Aktivierung, auch Tendenznoten einzutragen, also 1-, 3+, 4- usw. Ansonsten sind lediglich die glatten Noten zugelassen.</li><li><strong>Noteneingabe gesperrt</strong> verhindert das Eintragen und Ändern von Noten in den Leistungsdaten. Aktivieren Sie die Sperre zum Beispiel nach Abschluss der Notensammlung oder der Zeugniskonferenzen.</li><li><strong>Mindestnote für geholte Fächer</strong> stellt ein, welche Mindestnote vorliegen muss, damit abgeschlossene Fächer geholt werden.</li></ul><h2 id="eingabemodus" tabindex="-1">Eingabemodus <a class="header-anchor" href="#eingabemodus" aria-label="Permalink to &quot;Eingabemodus&quot;">​</a></h2><p><a href="/bilder/benutzer-einstellungen/verwaltung-einstellungen-faecher-noten-eingabemodus.png"><img src="'+o+'" alt="Wählen des Eingabemodus für Teilleistungen und Fehlstunden." loading="lazy"></a></p><p><em>Wählen des Eingabemodus für Teilleistungen und Fehlstunden.</em></p><p><strong>Eingabemodus für Teilleistungen</strong>: Hier kann zwischen zwei Modellen gewählt werden.</p><ul><li>Teilleistungen können <em>individuell von allen eingebenden Personen angelegt werden</em>, dabei stehen natürlich nur die Teilleistungen aus dem Katalog zur Verfügung.</li><li>Teilleistungen werden über die Gruppenprozesse vom <em>Administrator</em> vorbereitet und die Kollegen können dann nur noch die vorhandenen Teilleistungen &quot;füllen&quot;. Stimmen Sie die Vorbereitung mit dem an der Schule eingesetzten Verfahren zur Notenerfassung ab; für GradeHub und WeNoM ist die unten verlinkte SVWS-Dokumentation maßgeblich.</li></ul><p><strong>Sek I Modus für Gesamt-Fehlstunden&#39;</strong> beziehungsweise <strong>Sek II Modus für Gesamt-Fehlstunden</strong></p><ul><li><strong>Eingabe der Gesamt-Fehlstunden</strong>, zum Beispiel durch Klassenleitungen/Abteilungsleiter.</li><li><strong>Eingabe der Fachbezogenen-Fehlstunden</strong>, je nach Fach durch die Fachlehrkräfte.</li><li><strong>Tagesbezogenes Fehlstunden-Modell</strong>: nur durch Import aus einem anderen, tagesbezogene Fehlstunden unterstützenden Programm oder direkt in SchILD-NRW.</li></ul><p>Die Notenerfassung mit GradeHub und WeNoM ist dem SVWS-Server zugeordnet. Einrichtung und Bedienung sind in der <a href="https://doku.svws-nrw.de/" target="_blank" rel="noreferrer">SVWS-Dokumentation</a> beschrieben; siehe auch <a href="/zeugnisse/noteneingabe.html">Noten mit GradeHub und WeNoM erfassen</a>.</p>',9),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("Typisch ist, in der Sekundarstufe Fehlstunden gesamt zu erfassen und in der Sekundarstufe II über die Fächer/Kurse einzusammeln und über den ebenso benannten Gruppenprozess die "),e("em",null,"Gesamtfehlstunden"),n(" zu bilden.")])],-1),r('<h2 id="maximale-zeichenzahl-fur-bemerkungen" tabindex="-1">Maximale Zeichenzahl für Bemerkungen <a class="header-anchor" href="#maximale-zeichenzahl-fur-bemerkungen" aria-label="Permalink to &quot;Maximale Zeichenzahl für Bemerkungen&quot;">​</a></h2><p><a href="/bilder/benutzer-einstellungen/verwaltung-einstellungen-faecher-noten-max-bemerkungen.png"><img src="'+g+'" alt="Eingabe von maximalen Zeichenzahlen der Bemerkungsfelder." loading="lazy"></a></p><p><em>Eingabe von maximalen Zeichenzahlen der Bemerkungsfelder.</em></p><p>Hier begrenzen Sie bei Bedarf die Länge der folgenden Bemerkungsfelder:</p><ul><li>Zeugnisbemerkungen</li><li>außerunterrichtliches Engagement</li><li>Arbeits- und Sozialverhalten</li></ul><p>Eine <em>&quot;0&quot;</em> bedeutet, dass es keine Begrenzung gibt.</p><h2 id="farbeinstellungen-fur-fachergruppen" tabindex="-1">Farbeinstellungen für Fächergruppen <a class="header-anchor" href="#farbeinstellungen-fur-fachergruppen" aria-label="Permalink to &quot;Farbeinstellungen für Fächergruppen&quot;">​</a></h2><p><a href="/bilder/benutzer-einstellungen/verwaltung-einstellungen-faecher-noten-farben.png"><img src="'+d+'" alt="Einstellungen für die Einfärbung je nach Fachgruppe." loading="lazy"></a></p><p><em>Einstellungen für die Einfärbung je nach Fachgruppe.</em></p><p>Unter dieser Einstellungen lassen sich Einfärbungen der Fächergruppen setzen.</p><p>Dies kann die Lesbarkeit und den Überblick in den Leistungsdaten deutlich verbessern.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=F%C3%A4cher,_Noten_(Verwaltung_Globale_Einstellungen)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 3316.</p>',13)])])}const v=t(h,[["render",c]]);export{_ as __pageData,v as default};
